/** @file 已确认B的精确旧读/新身份/无损迁移与拒绝反例，冻结旧产物不从新写者改号生成。 @lang en Exact legacy reading, new identities, lossless migration and rejection cases for confirmed B; frozen artifacts are never regenerated by relabeling new writers. */
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFile, mkdtemp, writeFile, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { it, beforeEach } from 'node:test';
import * as spec from '../packages/dotnetdoc-spec/src/index.mjs';
import * as runner from '../packages/dotnetdoc-runner/src/index.mjs';
import * as adapter from '../packages/dotnetdoc-adapter/src/index.mjs';

/** 65ceafe旧实际写者清单是历史输入的唯一来源。 @lang en The actual 65ceafe legacy-writer manifest is the sole source for historical inputs. */
const manifest = JSON.parse(await readFile(new URL('./fixtures/legacy-contracts/manifest.json', import.meta.url), 'utf8'));
/** 新配置固定现有输入种类，目录省略保留原运行默认。 @lang en New configuration fixes existing input kinds and retains runtime defaults when directories are omitted. */
const oldConfig = { schemaVersion: '0.1.0-draft', inputs: [{ kind: 'dotnet-xml-doc', path: 'Sample.xml' }] };

// <lang><zh-CN>拒绝反例执行前先要求API存在，避免“调用undefined也抛TypeError”造成伪绿。</zh-CN><en>Require APIs before rejection cases so calling undefined cannot create a false-positive TypeError result.</en></lang>
beforeEach(() => {
  for (const name of ['readDotnetDocArtifact', 'migrateDotnetDocArtifact', 'getDotnetDocArtifactProfile', 'getDotnetDocArtifactSchema']) assert.equal(typeof spec[name], 'function', name);
  for (const name of ['readDotnetDocConfig', 'migrateDotnetDocConfig']) assert.equal(typeof runner[name], 'function', name);
});

for (const item of manifest.entries) {
  it(`keeps the real legacy bytes and exact read identity for ${item.contract}`, async () => {
    // <lang><zh-CN>先核冻结摘要，再读旧对象；不能通过改fixture适配新实现。</zh-CN><en>Verify the frozen digest before reading the legacy object; fixtures cannot be changed to fit the implementation.</en></lang>
    const bytes = await readFile(new URL(`./fixtures/legacy-contracts/${item.name}`, import.meta.url));
    assert.equal(createHash('sha256').update(bytes).digest('hex'), item.sha256);
    const value = JSON.parse(bytes);
    assert.equal(spec.readDotnetDocArtifact(value), value);
    assert.equal(value.contractVersion, '0.1.0-draft');
    assert.equal(spec.getDotnetDocArtifactProfile(item.contract, '0.1.0-draft').version, '0.1.0-draft');
  });

  it(`losslessly migrates ${item.contract} without rewriting provenance or references`, async () => {
    // <lang><zh-CN>迁移仅变根身份；源引用与生成时provenance仍真实指向旧输入/规则。</zh-CN><en>Migration changes root identity only; source references and production provenance continue to identify real legacy inputs/rules.</en></lang>
    const value = JSON.parse(await readFile(new URL(`./fixtures/legacy-contracts/${item.name}`, import.meta.url), 'utf8'));
    const before = structuredClone(value);
    const migrated = spec.migrateDotnetDocArtifact(value);
    assert.notEqual(migrated, value);
    assert.equal(migrated.contractVersion, '1.0.0');
    assert.equal(spec.readDotnetDocArtifact(migrated), migrated);
    assert.deepEqual({ ...migrated, contractVersion: '0.1.0-draft' }, before);
    assert.deepEqual(value, before);
    assert.equal(spec.getDotnetDocArtifactProfile(item.contract, '1.0.0').version, '1.0.0');
  });

  it(`rejects unknown versions and mismatched schema identities for ${item.contract}`, async () => {
    const value = JSON.parse(await readFile(new URL(`./fixtures/legacy-contracts/${item.name}`, import.meta.url), 'utf8'));
    assert.throws(() => spec.readDotnetDocArtifact({ ...value, contractVersion: '99.0.0' }), TypeError);
    assert.throws(() => spec.readDotnetDocArtifact({ ...value, $schema: 'https://invalid.example/private' }), TypeError);
    assert.equal(spec.getDotnetDocArtifactSchema(item.contract, '99.0.0'), undefined);
    assert.throws(() => spec.migrateDotnetDocArtifact({ ...value, contractVersion: '1.0.0' }), TypeError);
  });

  it(`updates only an existing schema identity when migrating ${item.contract}`, async () => {
    const value = JSON.parse(await readFile(new URL(`./fixtures/legacy-contracts/${item.name}`, import.meta.url), 'utf8'));
    value.$schema = spec.getDotnetDocArtifactSchema(item.contract, '0.1.0-draft').$id;
    const migrated = spec.migrateDotnetDocArtifact(value);
    assert.equal(migrated.$schema, spec.getDotnetDocArtifactSchema(item.contract, '1.0.0').$id);
    assert.equal(value.contractVersion, '0.1.0-draft');
    assert.throws(() => spec.readDotnetDocArtifact({ ...value, $schema: migrated.$schema }), TypeError);
  });

  it(`rejects missing payload collections in both generations of ${item.contract}`, async () => {
    const value = JSON.parse(await readFile(new URL(`./fixtures/legacy-contracts/${item.name}`, import.meta.url), 'utf8'));
    const schema = spec.getDotnetDocArtifactSchema(item.contract, '0.1.0-draft');
    const key = schema.required.find((name) => !['contract', 'contractVersion', 'producer', 'diagnostics'].includes(name));
    for (const version of ['0.1.0-draft', '1.0.0']) {
      const invalid = { ...value, contractVersion: version };
      delete invalid[key];
      assert.throws(() => spec.readDotnetDocArtifact(invalid), TypeError);
    }
  });
}

it('retains the original config schema while graduating the current identity', async () => {
  // <lang><zh-CN>原模块在改新schema之前已冻结，旧required不原位放宽。</zh-CN><en>The original module was frozen before changing the current schema; its required fields are not loosened in place.</en></lang>
  const legacy = await import('../packages/dotnetdoc-runner/src/schema-legacy.mjs');
  assert.equal(runner.DOTNETDOC_CONFIG_SCHEMA_VERSION, '1.0.0');
  assert.equal(legacy.DOTNETDOC_CONFIG_SCHEMA_VERSION, '0.1.0-draft');
  assert.deepEqual(legacy.DOTNETDOC_CONFIG_JSON_SCHEMA.required, ['schemaVersion', 'workspaceRoot', 'outputDirectory', 'inputs']);
  assert.deepEqual(runner.DOTNETDOC_CONFIG_JSON_SCHEMA.required, ['schemaVersion', 'inputs']);
});

it('reads omitted legacy directories exactly and migrates their runtime defaults without materializing them', () => {
  const value = structuredClone(oldConfig);
  assert.equal(runner.readDotnetDocConfig(value), value);
  const migrated = runner.migrateDotnetDocConfig(value);
  assert.deepEqual(migrated, { ...value, schemaVersion: '1.0.0' });
  assert.equal(Object.hasOwn(migrated, 'workspaceRoot'), false);
  assert.deepEqual(value, oldConfig);
});

it('retains legacy null defaults for reading but refuses a lossy null migration', () => {
  const value = { ...oldConfig, workspaceRoot: null, outputDirectory: null };
  assert.equal(runner.readDotnetDocConfig(value), value);
  assert.throws(() => runner.migrateDotnetDocConfig(value), TypeError);
  assert.throws(() => runner.readDotnetDocConfig({ ...value, schemaVersion: '1.0.0' }), TypeError);
});

it('loads real current and legacy config files using the same existing default directories', async (context) => {
  const root = await mkdtemp(path.join(tmpdir(), 'dotnetdoc-config-versions-'));
  context.after(() => rm(root, { recursive: true, force: true }));
  for (const schemaVersion of ['0.1.0-draft', '1.0.0']) {
    // <lang><zh-CN>loader只读配置并规范化请求，不需要真实输入文件或抽取执行。</zh-CN><en>The loader only reads config and normalizes a request; no actual input file or extraction is needed.</en></lang>
    const file = path.join(root, `${schemaVersion}.json`);
    await writeFile(file, JSON.stringify({ ...oldConfig, schemaVersion }));
    const result = await runner.loadDotnetDocConfig(file);
    assert.equal(result.workspaceRoot, root);
    assert.equal(result.outputDirectory, path.join(root, 'dist/dotnetdoc'));
  }
});

it('rejects unknown config versions, wrong schema pairings and unrecognized input kinds', () => {
  assert.throws(() => runner.readDotnetDocConfig({ ...oldConfig, schemaVersion: '99.0.0' }), TypeError);
  assert.throws(() => runner.readDotnetDocConfig({ ...oldConfig, $schema: 'https://invalid.example/private' }), TypeError);
  assert.throws(() => runner.readDotnetDocConfig({ schemaVersion: '1.0.0', inputs: [{ kind: 'future-input', path: 'sample' }] }), TypeError);
});

for (const [name, artifact] of [
  ['assertDotnetXmlDocArtifact', { contract: 'dotnetdoc-xml-doc-extraction', members: [] }],
  ['assertDotnetAspNetEndpointArtifact', { contract: 'dotnetdoc-aspnet-endpoint-extraction', endpoints: [] }],
  ['assertDotnetMarkupCommentArtifact', { contract: 'dotnetdoc-markup-comment-extraction', comments: [] }],
  ['assertDotnetProjectDiscoveryArtifact', { contract: 'dotnetdoc-project-discovery', projects: [], solutions: [] }]
]) {
  it(`rejects unknown artifact versions at the existing public ${name} boundary`, () => {
    assert.throws(() => adapter[name]({ ...artifact, contractVersion: '99.0.0' }), TypeError);
  });
}

it('preserves ordinary extension data, negative zero and repeated noncyclic values through migration', async () => {
  const value = JSON.parse(await readFile(new URL(`./fixtures/legacy-contracts/${manifest.entries[0].name}`, import.meta.url), 'utf8'));
  const shared = { score: -0 };
  value.extension = { first: shared, second: shared };
  const migrated = spec.migrateDotnetDocArtifact(value);
  assert.ok(Object.is(migrated.extension.first.score, -0));
  assert.deepEqual(migrated.extension, value.extension);
  assert.notEqual(migrated.extension.first, shared);
});

for (const [name, invalid] of [
  ['undefined', () => undefined], ['function', () => () => {}], ['infinite', () => Infinity],
  ['bigint', () => 1n], ['date', () => new Date(0)], ['sparse', () => new Array(2)],
  ['cycle', () => { const value = {}; value.self = value; return value; }]
]) {
  it(`rejects ${name} values during lossless migration rather than silently losing them`, async () => {
    const value = JSON.parse(await readFile(new URL(`./fixtures/legacy-contracts/${manifest.entries[0].name}`, import.meta.url), 'utf8'));
    value.extension = invalid();
    assert.throws(() => spec.migrateDotnetDocArtifact(value), TypeError);
  });
}

it('rejects getters without invoking them during reading or migration', async () => {
  const value = JSON.parse(await readFile(new URL(`./fixtures/legacy-contracts/${manifest.entries[0].name}`, import.meta.url), 'utf8'));
  let calls = 0;
  Object.defineProperty(value, 'extension', { enumerable: true, get() { calls++; return 'private'; } });
  assert.throws(() => spec.readDotnetDocArtifact(value), TypeError);
  assert.throws(() => spec.migrateDotnetDocArtifact(value), TypeError);
  assert.equal(calls, 0);
});

it('rejects proxy traps before reflection can execute caller behavior', async () => {
  const value = JSON.parse(await readFile(new URL(`./fixtures/legacy-contracts/${manifest.entries[0].name}`, import.meta.url), 'utf8'));
  let calls = 0;
  value.extension = new Proxy({}, { ownKeys() { calls++; return []; } });
  assert.throws(() => spec.readDotnetDocArtifact(value), TypeError);
  assert.throws(() => spec.migrateDotnetDocArtifact(value), TypeError);
  assert.equal(calls, 0);
});

it('copies prototype-named JSON fields as ordinary data without prototype pollution', async () => {
  const value = JSON.parse(await readFile(new URL(`./fixtures/legacy-contracts/${manifest.entries[0].name}`, import.meta.url), 'utf8'));
  value.extension = JSON.parse('{"__proto__":{"polluted":true}}');
  const migrated = spec.migrateDotnetDocArtifact(value);
  assert.equal(Object.getPrototypeOf(migrated.extension), Object.prototype);
  assert.equal(Object.hasOwn(migrated.extension, '__proto__'), true);
  assert.equal({}.polluted, undefined);
});

it('rejects legacy config values that cannot be represented in current configuration without loss', () => {
  const value = { ...oldConfig, options: { writeResultManifest: 0 } };
  assert.equal(runner.readDotnetDocConfig(value), value);
  assert.throws(() => runner.migrateDotnetDocConfig(value), TypeError);
  assert.throws(() => runner.readDotnetDocConfig({ ...oldConfig, schemaVersion: '1.0.0', inputs: [{ path: 'Sample.xml' }] }), TypeError);
});
